#!/usr/bin/env node
// sync-translate-prompts.mjs — regenerate api/src/translate/prompts/translate*.ts
// from a bp-assistant-skills checkout (issue #445, design §A "Prompt fidelity").
//
// The Worker cannot read SKILL.md off disk the way the bot does, so each
// translate skill's body (YAML frontmatter stripped, trimmed — the exact
// algorithm of translate-llm.js stripFrontmatter) is checked in as a string
// constant. Re-run this whenever the skills repo changes a translate-* skill,
// then commit the regenerated files; api/src/translate/prompts.test.mjs
// compares the constants against the checkout when one is present.
//
// Usage (from repo root):
//   node scripts/sync-translate-prompts.mjs [--skills <bp-assistant-skills dir>] [--out <prompts dir>]
//   BP_SKILLS_DIR=<dir> node scripts/sync-translate-prompts.mjs

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import path from "node:path";

const SKILLS = [
  { skill: "translate-tn", file: "translateTn.ts", constant: "TRANSLATE_TN_SKILL_BODY" },
  { skill: "translate-tq", file: "translateTq.ts", constant: "TRANSLATE_TQ_SKILL_BODY" },
  { skill: "translate-article", file: "translateArticle.ts", constant: "TRANSLATE_ARTICLE_SKILL_BODY" },
];

const DEFAULT_SKILLS_DIRS = [
  process.env.BP_SKILLS_DIR,
  "C:/GH/bp-bot/bp-assistant-skills",
  path.resolve(process.env.HOME || process.env.USERPROFILE || ".", "bp-bot/bp-assistant-skills"),
].filter(Boolean);

function arg(name) {
  const i = process.argv.indexOf(name);
  return i !== -1 ? process.argv[i + 1] : undefined;
}

// Verbatim port of bp-assistant src/lib/translate-llm.js stripFrontmatter.
export function stripFrontmatter(text) {
  const normalized = text.replace(/^\uFEFF/, "");
  if (!/^---\r?\n/.test(normalized)) return normalized.trim();
  const end = normalized.indexOf("\n---", 3);
  if (end === -1) return normalized.trim();
  const after = normalized.indexOf("\n", end + 1);
  return (after === -1 ? "" : normalized.slice(after + 1)).trim();
}

export function skillMarkdownPath(skillsDir, skill) {
  return path.join(skillsDir, ".claude", "skills", skill, "SKILL.md");
}

export function renderPromptModule({ skill, constant, body, sha256 }) {
  return [
    `// GENERATED by scripts/sync-translate-prompts.mjs — do not edit by hand.`,
    `// Source: bp-assistant-skills/.claude/skills/${skill}/SKILL.md, YAML frontmatter`,
    `// stripped and trimmed exactly as bp-assistant translate-llm.js readSkillBody does.`,
    `// sha256(body) = ${sha256}`,
    `// Regenerate: node scripts/sync-translate-prompts.mjs`,
    ``,
    `export const ${constant}: string = ${JSON.stringify(body)};`,
    ``,
  ].join("\n");
}

function main() {
  const skillsDir = arg("--skills") || DEFAULT_SKILLS_DIRS.find((d) => existsSync(d));
  if (!skillsDir || !existsSync(skillsDir)) {
    console.error("sync-translate-prompts: no bp-assistant-skills checkout found; pass --skills <dir> or set BP_SKILLS_DIR");
    process.exit(2);
  }
  const outDir = arg("--out") || fileURLToPath(new URL("../api/src/translate/prompts/", import.meta.url));
  mkdirSync(outDir, { recursive: true });

  for (const { skill, file, constant } of SKILLS) {
    const src = skillMarkdownPath(skillsDir, skill);
    if (!existsSync(src)) {
      console.error(`sync-translate-prompts: missing ${src}`);
      process.exit(2);
    }
    const body = stripFrontmatter(readFileSync(src, "utf8"));
    const sha256 = createHash("sha256").update(body, "utf8").digest("hex");
    const out = path.join(outDir, file);
    writeFileSync(out, renderPromptModule({ skill, constant, body, sha256 }), "utf8");
    console.log(`wrote ${out} (${body.length} chars, sha256 ${sha256.slice(0, 12)})`);
  }
}

const invokedDirectly = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) main();
